<template>    <div        v-for="(item, index) in (Array.isArray(selectData) ? selectData : [selectData])" :key="index"        class="flex my-4"    >        <image-contain            class="flex-none"            :src="item.image"            :width="70"            :height="70"            :radius="12"            :preview-src-list="[item.image]"            preview-teleported="true"            fit="contain"        />        <div class="ml-4">            <div class="font-medium">{{ item.name }}</div>            <template v-if="item.sku.length > 1">                <el-tag class="mt-2" :checked="true">多规格</el-tag>            </template>            <template v-else>                <el-tag class="mt-2" :checked="true">单规格</el-tag>            </template>        </div>    </div></template><script lang="ts" setup>import {useVModels} from '@vueuse/core';import {withDefaults} from "vue";const props = withDefaults(    defineProps<{        modelValue?: any    }>(),    {        modelValue: []    })const emit = defineEmits(['update:modelValue']);const {modelValue: selectData} = useVModels(props, emit);</script>